<first_data>
Here's a simple implementation of a number guessing game in JavaScript:

```javascript
function computerGuessNumber(min, max) {
  const userNumber = Math.floor(Math.random() * (max - min + 1)) + min;
  let guess;

  while (true) {
    guess = Math.floor((min + max) / 2);
    console.log(`Is your number more, less, or equal to ${guess}?`);

    const userResponse = prompt("Enter 'more', 'less', or 'equal'").toLowerCase();

    if (userResponse === "equal") {
      console.log("The computer guessed your number!");
      break;
    } else if (userResponse === "more") {
      min = guess + 1;
    } else if (userResponse === "less") {
      max = guess - 1;
    } else {
      console.log("Invalid input. Please enter 'more', 'less', or 'equal'.");
      continue;
    }
  }
}

// Example usage:
const min = 1;
const max = 100;
console.log(`Think of a number between ${min} and ${max}.`);
computerGuessNumber(min, max);
```

This script defines a function `computerGuessNumber` that takes a minimum and maximum value for the range. The computer generates a random number within that range and then starts guessing the user's number using a binary search algorithm. The user provides feedback by entering "more", "less", or "equal" in response to the computer's guesses. The game continues until the computer correctly guesses the user's number.
</first_data>

<second_data>
Here's a simple implementation of a guessing game in JavaScript. This game will guess a number between a range set by the user. The user will provide feedback to the computer's guesses by saying "more" or "less".

```javascript
let readline = require('readline').createInterface({
    input: process.stdin,
    output: process.stdout
});

let min = 1;
let max = 100;
let guess = Math.floor((min + max) / 2);

console.log(`Think of a number between ${min} and ${max}.`);

function askQuestion() {
    readline.question(`Is your number ${guess}? (yes/more/less) `, answer => {
        if (answer.toLowerCase() === 'yes') {
            console.log(`I guessed your number! It's ${guess}!`);
            readline.close();
        } else if (answer.toLowerCase() === 'more') {
            min = guess + 1;
            guess = Math.floor((min + max) / 2);
            askQuestion();
        } else if (answer.toLowerCase() === 'less') {
            max = guess - 1;
            guess = Math.floor((min + max) / 2);
            askQuestion();
        } else {
            console.log('Invalid input. Please answer "yes", "more", or "less".');
            askQuestion();
        }
    });
}

askQuestion();
```

This script uses the `readline` module to get user input. It starts by guessing the middle number of the range. Based on the user's feedback, it adjusts the range and makes a new guess. If the user's number is not within the range, the script will prompt the user to think of a number within the range.
</second_data>

